export const samplerDefaults={wrapS:'repeat',wrapT:'repeat',wrapR:'repeat',minFilter:'linear',magFilter:'linear',mipmaps:true,anisotropy:1};
export function validSamplerState(value){return value===undefined||value&&typeof value==='object'&&!Array.isArray(value)&&Object.keys(value).every(k=>Object.hasOwn(samplerDefaults,k))&&['wrapS','wrapT','wrapR'].every(k=>value[k]===undefined||['repeat','clamp','mirror'].includes(value[k]))&&['minFilter','magFilter'].every(k=>value[k]===undefined||['linear','nearest'].includes(value[k]))&&(value.mipmaps===undefined||typeof value.mipmaps==='boolean')&&(value.anisotropy===undefined||Number.isInteger(value.anisotropy)&&value.anisotropy>=1&&value.anisotropy<=16)&&(value.anisotropy<=1||value.anisotropy===undefined||((value.minFilter??'linear')==='linear'&&(value.magFilter??'linear')==='linear'));}
export function applySamplerState(THREE,map,value={},fallback='repeat'){if(!validSamplerState(value))throw Error('텍스처 샘플러 상태 오류');const p={...samplerDefaults,wrapS:fallback,wrapT:fallback,wrapR:fallback,...value},wrap={repeat:THREE.RepeatWrapping,clamp:THREE.ClampToEdgeWrapping,mirror:THREE.MirroredRepeatWrapping};for(const k of ['wrapS','wrapT','wrapR'])map[k]=wrap[p[k]];map.generateMipmaps=p.mipmaps;map.anisotropy=p.anisotropy;map.magFilter=p.magFilter==='nearest'?THREE.NearestFilter:THREE.LinearFilter;map.minFilter=p.mipmaps?(p.minFilter==='nearest'?THREE.NearestMipmapNearestFilter:THREE.LinearMipmapLinearFilter):(p.minFilter==='nearest'?THREE.NearestFilter:THREE.LinearFilter);map.needsUpdate=true;return map;}
// Legacy sampler IDs stay valid; extended IDs carry independent min/mag/mip.
export function nativeSamplerState(THREE,t){
 if(!t)return 0;const wrap=v=>v===THREE.RepeatWrapping?0:v===THREE.MirroredRepeatWrapping?1:2,mag=t.magFilter===THREE.NearestFilter,base=Number(mag)+wrap(t.wrapS)*2+wrap(t.wrapT)*6+wrap(t.wrapR)*18;
 const min=[THREE.NearestFilter,THREE.NearestMipmapNearestFilter,THREE.NearestMipmapLinearFilter].includes(t.minFilter),mipLinear=[THREE.LinearMipmapLinearFilter,THREE.NearestMipmapLinearFilter].includes(t.minFilter),noMip=[THREE.NearestFilter,THREE.LinearFilter].includes(t.minFilter),aniso=Math.max(1,Math.min(16,Math.floor(t.anisotropy||1)));
 if(min===mag&&!noMip&&mipLinear===!mag&&aniso===1)return base;
 return 65536|base|(min?128:0)|(noMip?256:0)|(mipLinear?512:0)|((aniso-1)<<10);
}
